// Package rules exposes the admin-editable pipeline "rules" (planner,
// grouping and detection knobs) over HTTP:
//
//	GET   /api/rules            every section, field, effective value
//	PATCH /api/rules/{section}  admin only: {"set": {...}, "reset": [...]}
//
// The schema (sections, fields, kinds, defaults) is generated by the
// Python pipeline and checked in as schema.json; it is embedded here and
// must not be edited by hand. Overrides live in “app_settings“, one row
// per section under key “rules.<section>“, whose value is a JSON object
// holding ONLY the settings that differ from their defaults.
package rules

import (
	"bytes"
	"context"
	"database/sql"
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/go-chi/chi/v5"

	"github.com/Hamza-Labs-Core/Maktaba/api/internal/auth/principal"
	"github.com/Hamza-Labs-Core/Maktaba/api/internal/handlers/common"
	"github.com/Hamza-Labs-Core/Maktaba/api/internal/httperror"
)

//go:embed schema.json
var schemaJSON []byte

// KeyPrefix is the app_settings key prefix for a rules section.
const KeyPrefix = "rules."

// maxPatchBytes bounds the PATCH body; row tables (themes, dayparts)
// are the largest values and stay well under this.
const maxPatchBytes = 512 << 10

// Handler bundles deps.
type Handler struct {
	DB      *sql.DB
	NowFunc func() time.Time
	// Schema overrides the embedded schema (tests). Nil → embedded.
	Schema *Schema

	initOnce sync.Once
	schema   *Schema
	initErr  error
	locks    sync.Map // section key -> *sync.Mutex
}

func (h *Handler) Mount(r chi.Router) {
	r.Get("/api/rules", h.Read)
	r.Patch("/api/rules/{section}", h.Patch)
}

func (h *Handler) loadSchema() (*Schema, error) {
	h.initOnce.Do(func() {
		if h.Schema != nil {
			h.schema = h.Schema
			return
		}
		h.schema, h.initErr = ParseSchema(schemaJSON)
	})
	return h.schema, h.initErr
}

// Read implements GET /api/rules. The global auth gate already requires
// a signed-in principal, matching GET /api/settings.
func (h *Handler) Read(w http.ResponseWriter, r *http.Request) {
	s, err := h.loadSchema()
	if err != nil {
		httperror.Write(w, r, httperror.Internal("rules schema: "+err.Error()))
		return
	}
	stored, err := h.loadAll(r.Context(), h.DB)
	if err != nil {
		httperror.Write(w, r, httperror.Internal("read rules: "+err.Error()))
		return
	}
	out := make([]map[string]any, 0, len(s.Sections))
	for _, sec := range s.Sections {
		st := stored[sec.Key]
		fields := make([]map[string]any, 0, len(sec.Fields))
		for _, f := range sec.Fields {
			m := make(map[string]any, len(f.raw)+3)
			for k, v := range f.raw {
				m[k] = v
			}
			m["value"] = f.Default
			m["changed"] = false
			if raw, ok := st.values[f.Name]; ok {
				v, verr := decodeValue(raw)
				if verr == nil {
					verr = f.Validate(v)
				}
				if verr != nil {
					m["invalid"] = verr.Error()
					m["changed"] = true
				} else {
					m["value"] = raw
					m["changed"] = !equalValues(f, v, f.def)
				}
			}
			fields = append(fields, m)
		}
		unknown := []string{}
		for name := range st.values {
			if sec.field(name) == nil {
				unknown = append(unknown, name)
			}
		}
		sort.Strings(unknown)
		item := map[string]any{
			"key":     sec.Key,
			"title":   sec.Title,
			"what":    sec.What,
			"fields":  fields,
			"unknown": unknown,
		}
		if st.err != "" {
			item["invalid"] = st.err
		}
		out = append(out, item)
	}
	common.WriteJSON(w, r, http.StatusOK, map[string]any{"sections": out})
}

// PatchRequest is the PATCH body.
type PatchRequest struct {
	Set   map[string]json.RawMessage `json:"set"`
	Reset []string                   `json:"reset"`
}

// Patch implements PATCH /api/rules/{section}.
func (h *Handler) Patch(w http.ResponseWriter, r *http.Request) {
	p := principal.FromContext(r.Context())
	if p == nil || !p.IsAdmin {
		httperror.Write(w, r, httperror.Forbidden("", "admin-only"))
		return
	}
	s, err := h.loadSchema()
	if err != nil {
		httperror.Write(w, r, httperror.Internal("rules schema: "+err.Error()))
		return
	}
	sec := s.section(chi.URLParam(r, "section"))
	if sec == nil {
		httperror.Write(w, r, httperror.NotFound("unknown rules section"))
		return
	}
	if h.DB == nil {
		httperror.Write(w, r, httperror.Internal("rules: no database"))
		return
	}
	var req PatchRequest
	if e := common.ReadJSON(r, &req, maxPatchBytes); e != nil {
		httperror.Write(w, r, e)
		return
	}

	// Validate everything before touching the DB. Names are checked in
	// sorted order so the "first problem" is deterministic.
	names := make([]string, 0, len(req.Set))
	for name := range req.Set {
		names = append(names, name)
	}
	sort.Strings(names)
	parsed := make(map[string]any, len(names))
	for _, name := range names {
		f := sec.field(name)
		if f == nil {
			writeFieldError(w, r, name, errors.New("unknown setting"))
			return
		}
		v, verr := decodeValue(req.Set[name])
		if verr == nil {
			verr = f.Validate(v)
		}
		if verr != nil {
			writeFieldError(w, r, name, verr)
			return
		}
		parsed[name] = v
	}

	// Serialise PATCHes of one section within this process (works for
	// SQLite); on Postgres an advisory transaction lock also covers
	// multiple API replicas.
	mu, _ := h.locks.LoadOrStore(sec.Key, &sync.Mutex{})
	mu.(*sync.Mutex).Lock()
	defer mu.(*sync.Mutex).Unlock()

	ctx := r.Context()
	key := KeyPrefix + sec.Key
	tx, err := h.DB.BeginTx(ctx, nil)
	if err != nil {
		httperror.Write(w, r, httperror.Internal("begin: "+err.Error()))
		return
	}
	defer func() { _ = tx.Rollback() }()
	if !isSQLite(h.DB) {
		if _, err := tx.ExecContext(ctx, `SELECT pg_advisory_xact_lock(hashtext($1))`, key); err != nil {
			httperror.Write(w, r, httperror.Internal("lock rules: "+err.Error()))
			return
		}
	}
	current, err := loadOne(ctx, tx, key)
	if err != nil {
		httperror.Write(w, r, httperror.Internal("read rules: "+err.Error()))
		return
	}

	next := map[string]json.RawMessage{}
	for name, raw := range current.values {
		if sec.field(name) != nil {
			next[name] = raw
		}
	}
	for _, name := range req.Reset {
		delete(next, name)
	}
	for _, name := range names {
		next[name] = req.Set[name]
	}
	changed := []string{}
	for name, raw := range next {
		f := sec.field(name)
		v, derr := decodeValue(raw)
		if derr == nil && equalValues(f, v, f.def) {
			delete(next, name)
			continue
		}
		changed = append(changed, name)
	}
	sort.Strings(changed)

	if len(next) == 0 {
		_, err = tx.ExecContext(ctx, `DELETE FROM app_settings WHERE key = $1`, key)
	} else {
		var body []byte
		body, err = marshalOverrides(next)
		if err == nil {
			var by any
			if p.UserID != "" {
				by = p.UserID
			}
			_, err = tx.ExecContext(ctx, `
				INSERT INTO app_settings (key, value, updated_at, updated_by)
				VALUES ($1, $2, $3, $4)
				ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = EXCLUDED.updated_at, updated_by = EXCLUDED.updated_by
			`, key, string(body), h.now(), by)
		}
	}
	if err != nil {
		httperror.Write(w, r, httperror.Internal("write rules: "+err.Error()))
		return
	}
	if err := tx.Commit(); err != nil {
		httperror.Write(w, r, httperror.Internal("commit: "+err.Error()))
		return
	}
	common.WriteJSON(w, r, http.StatusOK, map[string]any{"section": sec.Key, "changed": changed})
}

func writeFieldError(w http.ResponseWriter, r *http.Request, field string, err error) {
	msg := field + ": " + err.Error()
	httperror.Write(w, r, httperror.BadRequest(msg).With("error", msg).With("field", field))
}

// storedSection is one decoded app_settings row.
type storedSection struct {
	values map[string]json.RawMessage
	err    string // the row exists but is not a JSON object
}

type querier interface {
	QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows, error)
}

func (h *Handler) loadAll(ctx context.Context, q querier) (map[string]storedSection, error) {
	out := map[string]storedSection{}
	if h.DB == nil {
		return out, nil
	}
	rows, err := q.QueryContext(ctx, `SELECT key, value FROM app_settings WHERE key LIKE 'rules.%'`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var k string
		var v []byte
		if err := rows.Scan(&k, &v); err != nil {
			return nil, err
		}
		out[strings.TrimPrefix(k, KeyPrefix)] = decodeStored(v)
	}
	return out, rows.Err()
}

func loadOne(ctx context.Context, q querier, key string) (storedSection, error) {
	rows, err := q.QueryContext(ctx, `SELECT value FROM app_settings WHERE key = $1`, key)
	if err != nil {
		return storedSection{}, err
	}
	defer rows.Close()
	st := storedSection{values: map[string]json.RawMessage{}}
	if rows.Next() {
		var v []byte
		if err := rows.Scan(&v); err != nil {
			return st, err
		}
		st = decodeStored(v)
	}
	return st, rows.Err()
}

func decodeStored(v []byte) storedSection {
	st := storedSection{values: map[string]json.RawMessage{}}
	if err := json.Unmarshal(v, &st.values); err != nil || st.values == nil {
		st.values = map[string]json.RawMessage{}
		st.err = "stored value is not a JSON object"
	}
	return st
}

// marshalOverrides writes the overrides compactly with sorted keys.
func marshalOverrides(m map[string]json.RawMessage) ([]byte, error) {
	compact := make(map[string]json.RawMessage, len(m))
	for k, raw := range m {
		var buf bytes.Buffer
		if err := json.Compact(&buf, raw); err != nil {
			return nil, fmt.Errorf("%s: %w", k, err)
		}
		compact[k] = buf.Bytes()
	}
	return json.Marshal(compact)
}

func isSQLite(db *sql.DB) bool {
	return strings.Contains(strings.ToLower(fmt.Sprintf("%T", db.Driver())), "sqlite")
}

func (h *Handler) now() time.Time {
	if h.NowFunc != nil {
		return h.NowFunc()
	}
	return time.Now().UTC()
}
